<?php
require_once __DIR__.'/../../includes/accounting_ui.php';$student=(int)($_GET['student']??$_GET['student_id']??0);
acHandle(function()use($ac,$student){if(($_POST['action']??'')==='refund')return $ac->refundAdvance($_POST+['student_id'=>$student]);if(($_POST['action']??'')==='opening')return $ac->openingDue($_POST+['student_id'=>$student]);throw new InvalidArgumentException('Unsupported student financial action.');},'student',['student'=>$student]);
$s=$student?schoolRecord($db,'students',$student,$school):[];ob_start();
?>
<form method="get" class="card card-body mb-3"><?php acStudentPicker($student,true); ?><button class="btn btn-primary align-self-start">Open account</button></form>
<?php if($s): ?><h3><?= sanitize($s['first_name_en'].' '.$s['last_name_en']) ?> · <?= sanitize($s['student_id']) ?></h3><div class="ac-stats mb-3"><div class="ac-stat"><small>Outstanding dues across all years</small><strong><?= acMoney($ac->outstanding($student)) ?></strong></div><div class="ac-stat"><small>Available student advance</small><strong><?= acMoney($ac->advanceBalance($student)) ?></strong></div></div><div class="d-flex gap-2 mb-3 no-print"><a class="btn btn-primary" href="<?= acUrl('payments',['student'=>$student]) ?>">Collect payment</a><a class="btn btn-outline-secondary" href="<?= acUrl('create_bill',['student'=>$student]) ?>">Create bill</a><button class="btn btn-outline-secondary" onclick="window.print()">Print / Save PDF</button></div>
<div class="card card-body table-responsive"><h4>Student ledger / account statement</h4><table class="table"><thead><tr><th>Date</th><th>Journal</th><th>Details</th><th>Account</th><th>Debit</th><th>Credit</th><th>Due balance</th><th>Advance balance</th></tr></thead><tbody><?php $due=0;$advance=0;foreach($ac->studentStatement($student) as $l):if($l['control_key']==='receivable')$due+=(int)$l['debit_minor']-(int)$l['credit_minor'];else $advance+=(int)$l['credit_minor']-(int)$l['debit_minor']; ?><tr><td><?= sanitize(schoolDateLabel($l['posting_date'],'both','ymd')) ?></td><td><?= sanitize($l['number']) ?></td><td><?= sanitize($l['description']) ?></td><td><?= sanitize($l['name']) ?></td><td><?= acMoney((int)$l['debit_minor']) ?></td><td><?= acMoney((int)$l['credit_minor']) ?></td><td><?= acMoney($due) ?></td><td><?= acMoney($advance) ?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="card card-body mt-3"><h4>Invoices from all academic sessions</h4><?php foreach($ac->rows('SELECT * FROM ac_invoices WHERE school_id=? AND student_id=? ORDER BY bill_date,id',[$school,$student]) as $i): ?><p><a href="<?= acUrl('invoice',['id'=>$i['id']]) ?>"><?= sanitize($i['number']?:'Draft #'.$i['id']) ?></a> · <?= acMoney((int)$i['total_minor']) ?> · Remaining <?= acMoney($ac->invoiceBalance((int)$i['id'])) ?></p><?php endforeach; ?></div>
<?php if($ac->can('refund')): ?><details class="no-print mt-3"><summary>Approved advance refund</summary><?php acForm('refund');acInput('amount','Refund amount (NPR)','0.00','number');acInput('date','Refund date',date('Y-m-d'),'date');acInput('reason','Reason');acSelect('account_id','Cash / bank account',$ac->rows("SELECT * FROM ac_accounts WHERE school_id=? AND type='asset' AND (control_key IS NULL OR control_key IN ('cash','bank'))",[$school])); ?><label><input type="checkbox" name="confirm" value="1" required> I authorize this refund from available advance only</label><?php acSubmit('Approve refund'); ?></details><?php endif; ?>
<?php if($ac->can('opening')): ?><details class="no-print mt-3"><summary>Import independently verified opening due</summary><?php acForm('opening');acInput('amount','Verified previous due (NPR)','0.00','number');acInput('date','Opening posting date',date('Y-m-d'),'date');acInput('reason','Verification reference / explanation'); ?><label><input type="checkbox" name="confirm" value="1" required> I verified this balance and it has not already been imported</label><?php acSubmit('Post opening due without new revenue'); ?></details><?php endif; ?>
<?php endif;acRender('Student financial accounts',ob_get_clean());
